bool CAIStateGroup_SkillPractice::IsRunnable()
{
    if (FrameToCheckForDummy < GFGetFrameCount()) {
        if (GetDummy())
            return true;
        long fps = g_framesPerSecond;
        FrameToCheckForDummy = GFGetFrameCount() + fps * 60;
    }
    return false;
}

